import { MeshBasicNodeMaterial, PlaneGeometry } from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const group = new THREE.Group();
  group.userData.handlers = {};

  // Colors from spec
  const ink = new THREE.Color('#16161d');
  const paper = new THREE.Color('#e8ecf2');
  const accent = new THREE.Color('#ff2a38');
  const surface = new THREE.Color('#0b0b10');

  // Plane geometry with aspect ratio from source rect (512x320)
  const width = 1.5;
  const height = width * (320 / 512); // ≈ 0.9375
  const geometry = new PlaneGeometry(width, height);

  // Material with paper color as fallback; texture will be loaded
  const material = new MeshBasicNodeMaterial({
    color: paper,
    roughness: 0.6,
    metalness: 0.4,
  });

  const mesh = new THREE.Mesh(geometry, material);
  group.add(mesh);

  // Load the brushed metal texture
  let texture = null;
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      texture = tex;
      material.map = tex;
      material.needsUpdate = true;
    });
  }

  // Cleanup
  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (texture) texture.dispose();
    // No GSAP timelines to kill
  };

  return group;
}
